import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"엔드포인트","description":"","frontmatter":{},"headers":[],"relativePath":"ko/concepts/endpoints.md","filePath":"ko/concepts/endpoints.md","lastUpdated":1784903584000}'),o={name:"ko/concepts/endpoints.md"};function d(p,a,c,i,r,l){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="엔드포인트" tabindex="-1">엔드포인트 <a class="header-anchor" href="#엔드포인트" aria-label="Permalink to &quot;엔드포인트&quot;">​</a></h1><p>엔드포인트는 호출할 수 있는 특정 HTTP 메서드 + 경로입니다(예: <code>GET /api/users/{id}</code>). 엔드포인트는 LLM이 발견, 검사, 호출하는 실제 API 작업입니다.</p><h2 id="구조" tabindex="-1">구조 <a class="header-anchor" href="#구조" aria-label="Permalink to &quot;구조&quot;">​</a></h2><p>각 엔드포인트에는 다음이 포함됩니다:</p><ul><li><strong>HTTP 메서드</strong>: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS</li><li><strong>경로</strong>: <code>/api/v1/users/{id}</code></li><li><strong>요약</strong>: 엔드포인트가 무엇을 하는지에 대한 짧은 설명 — LLM이 한눈에 목적을 이해하는 데 매우 유용</li><li><strong>설명</strong>: 엔드포인트의 동작, 매개변수, 사용 사례에 대한 상세 설명</li><li><strong>매개변수</strong>: path, query, header, cookie</li><li><strong>요청 본문</strong>: POST/PUT/PATCH용</li><li><strong>응답</strong>: 상태 코드 및 응답 스키마</li></ul><p><code>summary</code>와 <code>description</code> 필드는 OpenAPI/Swagger/Postman 파일에서 가져옵니다. 이는 LLM이 엔드포인트의 기능을 이해하는 기본 방법입니다. 잘 작성된 요약은 엔드포인트 발견을 훨씬 더 효과적으로 만듭니다.</p><h2 id="엔드포인트용-mcp-도구" tabindex="-1">엔드포인트용 MCP 도구 <a class="header-anchor" href="#엔드포인트용-mcp-도구" aria-label="Permalink to &quot;엔드포인트용 MCP 도구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>도구</th><th>설명</th></tr></thead><tbody><tr><td><code>endpoint_by_spec</code></td><td>spec의 모든 엔드포인트</td></tr><tr><td><code>endpoint_by_collection</code></td><td>collection의 엔드포인트</td></tr><tr><td><code>endpoint_by_tag</code></td><td>태그의 엔드포인트</td></tr><tr><td><code>endpoint_by_id</code></td><td>빠른 엔드포인트 요약</td></tr><tr><td><code>inspect</code></td><td>전체 엔드포인트 상세 (스키마, 매개변수)</td></tr><tr><td><code>invoke</code></td><td>엔드포인트 호출</td></tr><tr><td><code>search</code></td><td>텍스트로 엔드포인트 검색</td></tr></tbody></table><h2 id="폐기된-엔드포인트" tabindex="-1">폐기된 엔드포인트 <a class="header-anchor" href="#폐기된-엔드포인트" aria-label="Permalink to &quot;폐기된 엔드포인트&quot;">​</a></h2><p>명세에서 <code>deprecated</code>로 표시된 엔드포인트는 검사 시 알림과 함께 표시됩니다.</p><h2 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h2><p>엔드포인트는 swag2mcp 관점에서 <strong>읽기 전용</strong>입니다. 엔드포인트에 대한 YAML 설정이 없습니다 — <code>swag2mcp.yaml</code>에서 엔드포인트를 추가, 제거, 이름 변경 또는 수정할 수 없습니다.</p><p>엔드포인트를 변경하려면(새로 추가, 요약 업데이트, 매개변수 수정, 폐기 표시) 원본 OpenAPI/Swagger/Postman 파일을 편집하고 <code>swag2mcp update</code>를 실행하여 다시 파싱하고 재인덱싱하세요.</p><h2 id="예시" tabindex="-1">예시 <a class="header-anchor" href="#예시" aria-label="Permalink to &quot;예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>쿼리: &quot;GET /pet/{petId}의 세부 정보 표시&quot;</span></span>
<span class="line"><span>→ inspect(endpointId: &quot;abc123...&quot;)</span></span>
<span class="line"><span>→ 결과:</span></span>
<span class="line"><span>  GET /pet/{petId}</span></span>
<span class="line"><span>  요약: ID로 애완동물 찾기</span></span>
<span class="line"><span>  설명: ID로 단일 애완동물 반환</span></span>
<span class="line"><span>  매개변수:</span></span>
<span class="line"><span>    - petId (path, integer, 필수)</span></span>
<span class="line"><span>  응답:</span></span>
<span class="line"><span>    - 200: Pet 객체</span></span>
<span class="line"><span>    - 400: 오류</span></span>
<span class="line"><span>    - 404: 찾을 수 없음</span></span></code></pre></div>`,15)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
